def transform(grid):
    """Stamp the marked nonzero shape wherever its cells cover zeros."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c not in (0, background)]
    if not colors:
        return [row[:] for row in grid]
    # The puzzle's marker is the sparse non-background, nonzero color.
    color = min(colors, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    minr = min(r for r, _ in points); maxr = max(r for r, _ in points)
    minc = min(c for _, c in points); maxc = max(c for _, c in points)
    shape = [(r-minr, c-minc) for r, c in points]
    sh, sw = maxr-minr+1, maxc-minc+1
    out = [row[:] for row in grid]
    for top in range(h-sh+1):
        for left in range(w-sw+1):
            if all(grid[top+dr][left+dc] in (0, color) for dr, dc in shape):
                for dr, dc in shape:
                    out[top+dr][left+dc] = color
    return out

